from scapy.all import PcapReader
from scapy.layers.inet import IP, TCP, UDP, ICMP
from scapy.layers.inet6 import IPv6
from scapy.layers.l2 import ARP
from collections import Counter

pcap_path = '/root/packets.pcap'
counts = {'ipv4':0,'ipv6':0,'arp':0,'tcp':0,'udp':0,'icmp':0}

with PcapReader(pcap_path) as p:
    for pkt in p:
        if ARP in pkt:
            counts['arp'] += 1
        if IP in pkt:
            counts['ipv4'] += 1
            if TCP in pkt:
                counts['tcp'] += 1
            elif UDP in pkt:
                counts['udp'] += 1
            elif ICMP in pkt:
                counts['icmp'] += 1
        elif IPv6 in pkt:
            counts['ipv6'] += 1
            if TCP in pkt:
                counts['tcp'] += 1
            elif UDP in pkt:
                counts['udp'] += 1
            elif ICMP in pkt:
                counts['icmp'] += 1

print(counts)
print('ip total', counts['ipv4']+counts['ipv6'])
